@layer components {
  :where([data-control-family="field"][data-field-kind="input-group"][data-slot="addon"]),

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]),

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-input-group-part="input"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    outline: none;
    background: transparent;
    color: var(--foreground);
  }

  :where([data-input-group-part="input"])::placeholder,

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"])::placeholder {
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]) {
    border-radius: var(--radius-control);
    outline: none;
    transition-property: color, box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) {
    :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:hover),

    :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:hover),

    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:hover),

    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:hover) {
      color: var(--foreground);
    }
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:focus-visible),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:focus-visible) {
    box-shadow: 0 0 0 2px var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:disabled),

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:disabled) {
    cursor: not-allowed;
    opacity: 0.45;
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"]) {
    transition-property: rotate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-popup-open] :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"])) {
    rotate: 180deg;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]) {
    border-inline-end: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    border-inline-start: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    outline: none;
    transition-property: color, background-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:active),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:active) {
    background: oklch(from var(--foreground) l c h / 0.06);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"][data-disabled]),

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"][data-disabled]) {
    color: oklch(from var(--muted-foreground) l c h / 0.5);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="scrub-cursor"]) {
    color: var(--foreground);
    filter: drop-shadow(0 1px 1px oklch(0 0 0 / 0.05));
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="separator"]) {
    border-radius: 9999px;
    background: var(--border);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="title"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 500;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 500;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="error"]) {
    color: var(--destructive-text);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator"]) {
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator-content"]) {
    background-color: var(--background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="set"]) {
    border-width: 0px;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="legend"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: 600;
  }
}

@layer components {
  :where([data-control-family="field"][data-control="true"]) {
    --field-radius: var(--radius-control);
    --field-background: oklch(from var(--card) l c h / 0.72);
    --field-foreground: var(--foreground);
    --field-border-color: var(--border);
    --field-border-width: 1px;
    --field-shadow: var(--shadow-sm);
    --field-backdrop-filter: blur(0px);
    --field-focus-border-color: var(--border);
    --field-focus-ring-color: var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
    --field-focus-ring-width: 2px;
    border: var(--field-border-width) solid var(--field-border-color);
    border-radius: var(--field-radius);
    outline: none;
    background: var(--field-background);
    box-shadow: var(--field-shadow);
    color: var(--field-foreground);
    backdrop-filter: var(--field-backdrop-filter);
  }

  :where([data-control-family="field"][data-control="true"]:not([data-control-family="field"][data-field-kind="autocomplete"]):not(
        [data-control-family="field"][data-field-kind="combobox"]
      )
  ) {
    transition-property: color, background-color, border-color, box-shadow, opacity, backdrop-filter;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-control="true"])::placeholder {
    color: var(--muted-foreground);
  }

  @media (hover: hover) {
    :where(
      [data-control-family="field"][data-field-kind="autocomplete"]:hover,
      [data-control-family="field"][data-field-kind="combobox"]:hover,
      [data-control-family="field"][data-field-kind="native-select"]:hover,
      [data-control-family="field"][data-field-kind="number-field"]:hover
    ) {
      background: oklch(from var(--foreground) l c h / 0.05);
    }
  }

  :where([data-control-family="field"][data-control="true"]:is(:focus-visible, :focus-within)) {
    border-color: var(--field-focus-border-color);
    box-shadow: 0 0 0 var(--field-focus-ring-width) var(--field-focus-ring-color), var(--field-shadow);
  }

  :where([data-control-family="field"][data-control="true"][data-invalid]),

  :where([data-control-family="field"][data-control="true"][aria-invalid="true"]) {
    box-shadow: 0 0 0 2px var(--destructive), var(--field-shadow);
  }

  :where([data-control-family="field"][data-control="true"]:disabled),

  :where([data-control-family="field"][data-control="true"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }


  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]) {
    --_field-input-otp-slot-text-align: center;
    text-align: var(--_field-input-otp-slot-text-align);
    font-size: var(--text-body);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="input"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="drag-icon"]) {
    color: var(--foreground);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    --_field-number-field-input-text-align: center;
    text-align: var(--_field-number-field-input-text-align);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="group"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="textarea"][data-slot="root"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="input"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]) {
    --_field-input-otp-slot-number-style: tabular-nums;
    font-variant-numeric: var(--_field-input-otp-slot-number-style);
  }

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    appearance: none;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    --_field-number-field-input-number-style: tabular-nums;
    font-variant-numeric: var(--_field-number-field-input-number-style);
  }
}

@property --field-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --field-background {
  syntax: "*";
  inherits: true;
}

@property --field-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --field-shadow {
  syntax: "*";
  inherits: true;
}

@property --field-backdrop-filter {
  syntax: "*";
  inherits: true;
}

@property --field-focus-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-focus-ring-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --field-focus-ring-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

"use client";

import { OTPField as OTPFieldPrimitive } from "@base-ui/react/otp-field";
import { Fragment } from "react";
import type { InputOTPProps, InputOTPSeparatorProps, InputOTPSlotProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function InputOTPSlot({ index, length, className, ...props }: InputOTPSlotProps) {
  return (
    <OTPFieldPrimitive.Input
      data-control-ui="input-otp"
      data-field-kind="input-otp"
      data-slot="slot"
      data-control-family="field"
      data-control="true"
      aria-label={length ? `Character ${index + 1} of ${length}` : `Character ${index + 1}`}
      className={cn("relative flex size-[var(--control-h-md)] items-center justify-center", className)}
      {...props}
    />
  );
}

export function InputOTPSeparator({ className, ...props }: InputOTPSeparatorProps) {
  return (
    <OTPFieldPrimitive.Separator
      data-control-ui="input-otp"
      data-control-family="field"
      data-field-kind="input-otp"
      data-slot="separator"
      className={cn("h-px w-2.5 shrink-0", className)}
      {...props}
    />
  );
}

export function InputOTP({ length = 6, separator = false, className, children, ...props }: InputOTPProps) {
  return (
    <OTPFieldPrimitive.Root
      data-control-ui="input-otp"
      data-control-family="field"
      data-field-kind="input-otp"
      data-slot="root"
      length={length}
      className={cn("flex items-center gap-2", className)}
      {...props}
    >
      {children ??
        Array.from({ length }, (_, index) => `input-otp-slot-${index}`).map((slotKey, index) => (
          <Fragment key={slotKey}>
            {separator && index === Math.ceil(length / 2) ? <InputOTPSeparator /> : null}
            <InputOTPSlot index={index} length={length} />
          </Fragment>
        ))}
    </OTPFieldPrimitive.Root>
  );
}
